import{_ as a,o as t,c as o,ae as r}from"./chunks/framework.BajMXG5H.js";const u=JSON.parse('{"title":"Orchestration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/orchestration.md","filePath":"guide/orchestration.md"}'),s={name:"guide/orchestration.md"};function n(i,e,l,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="orchestration" tabindex="-1">Orchestration <a class="header-anchor" href="#orchestration" aria-label="Permalink to &quot;Orchestration&quot;">​</a></h1><p>Orchestration lets you hand a <strong>goal</strong> to an orchestrator that plans the work, dispatches tasks to worker agents (Claude Code, Codex, Kimi Code CLI), checks the results, and finishes — while you watch the whole exchange as a live graph and a conversation.</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><ul><li><strong>Graph</strong>: the orchestrator sits at the top; each worker task is a node below it. The running node is enlarged and glows in its agent color, the edge to it animates, and a packet travels along the edge whenever an instruction goes down or a result comes back.</li><li><strong>Conversation</strong>: every dispatch and result is shown as a chat message with the speaker&#39;s avatar (Orchestrator → Kimi, Codex → Orchestrator, …), rendered as Markdown. While a worker is running you see a live &quot;working…&quot; indicator.</li><li><strong>Replay</strong>: finished goals can be replayed with the ▶ button at the bottom of the graph. Graph and conversation advance together; use the slider to seek and 1× / 2× / 4× to change the pace.</li><li>Drag the canvas to pan, scroll or pinch to zoom, and drag nodes to rearrange them. <strong>⊡ Fit</strong> brings everything back into view.</li></ul><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li><strong>Node.js</strong> (18 or newer) on your PATH — the orchestrator runs as a small Node.js sidecar bundled inside Orchestra. It is placed in <code>~/.orchestra/engine</code> and its dependencies are installed automatically the first time you start a goal (this takes a few seconds; the log is in <code>~/.orchestra/engine/install.log</code>).</li><li>The worker CLIs you want to use, logged in: <code>claude</code> (Claude Code), <code>codex</code> (Codex CLI), <code>kimi</code> (Kimi Code CLI). Only the agents you enable in the New Goal dialog are used.</li><li>The orchestrator itself runs on Claude (Opus by default) through the Claude Agent SDK, using your Claude Code login.</li></ul><h2 id="starting-a-goal" tabindex="-1">Starting a goal <a class="header-anchor" href="#starting-a-goal" aria-label="Permalink to &quot;Starting a goal&quot;">​</a></h2><ol><li>Open <strong>Orchestration</strong> in the sidebar and press <strong>＋</strong> (New Goal).</li><li>Write the goal as a self-contained brief: background, what to produce, done criteria, how to verify.</li><li>Pick the working directory. Workers run <strong>unattended</strong> in this directory and may create or edit files there, so use a dedicated folder for anything experimental.</li><li>Choose which agents (and optionally which models) the orchestrator may use, and optionally which agent should take the first task.</li><li>Set a cost cap and a dispatch limit, then <strong>Start Goal</strong>.</li></ol><p>The orchestrator registers a plan, dispatches tasks one by one, and calls <code>finish</code> when done. You can <strong>Stop</strong> a running goal from the header at any time; the engine and its running worker are terminated together.</p><h2 id="local-models-ollama" tabindex="-1">Local models (Ollama) <a class="header-anchor" href="#local-models-ollama" aria-label="Permalink to &quot;Local models (Ollama)&quot;">​</a></h2><p>If <a href="https://ollama.com" target="_blank" rel="noreferrer">Ollama</a> is running on your Mac, its models show up in the New Goal dialog as extra choices for Claude Code and Codex, labelled <code>(local)</code>. Orchestra drives them through the same CLIs — Codex with <code>--oss</code>, Claude Code through Ollama&#39;s Anthropic-compatible API — so hooks, attribution and cost tracking work unchanged, and local work is counted as $0.</p><p>Local models are slower and less capable than hosted ones; use them for light or mechanical tasks. On a 64 GB Mac, <code>qwen3:30b</code> (a mixture-of-experts model that runs about as fast as an 8B model) is a good default.</p><h2 id="duplicating-a-goal" tabindex="-1">Duplicating a goal <a class="header-anchor" href="#duplicating-a-goal" aria-label="Permalink to &quot;Duplicating a goal&quot;">​</a></h2><p>Hover a goal in the list and press <strong>⧉</strong> to open New Goal pre-filled with the same brief, directory, agents, and limits — handy for re-running experiments.</p><h2 id="safety-notes" tabindex="-1">Safety notes <a class="header-anchor" href="#safety-notes" aria-label="Permalink to &quot;Safety notes&quot;">​</a></h2><ul><li>Codex workers run in a workspace-write sandbox. Claude Code and Kimi workers run headless with permission prompts skipped, so treat the working directory as disposable.</li><li>The orchestrator stops by itself when the cost cap or the dispatch limit is reached.</li><li>Goal state and history live in <code>~/.orchestra/goals/&lt;id&gt;/</code> (<code>state.json</code>, <code>events.jsonl</code>, <code>engine.log</code>). Deleting a goal from the list removes that folder.</li></ul>',16)])])}const p=a(s,[["render",n]]);export{u as __pageData,p as default};
